package com.google.javascript.rhino;

import com.google.common.base.Preconditions;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class IR_tryFinally_TriageGen2Test {

    @Test
    public void testTryFinallySuccess() {
        // Create valid label nodes as required by Preconditions.checkState(node.isLabelName())
        Node tryBody = IR.labelName("tryLabel");
        Node finallyBody = IR.labelName("finallyLabel");

        // Execute the method under test
        Node result = IR.tryFinally(tryBody, finallyBody);

        // Assertions
        assertNotNull("The returned node should not be null", result);
        assertEquals("The token should be TRY", Token.TRY, result.getType());

        // Check children: 0: tryBody, 1: catchBody (copy of tryBody), 2: finallyBody
        assertEquals("The first child should be the tryBody", tryBody, result.getChild(0));
        assertEquals("The third child should be the finallyBody", finallyBody, result.getChild(2));

        // Verify that the catchBody (child 1) is a new node that copied information from tryBody
        Node catchBody = result.getChild(1);
        assertNotNull("The catchBody should be initialized", catchBody);
        assertTrue("The catchBody should be a block (as per block().copyInformationFrom)", catchBody.isBlock());
    }

    @Test(expected = IllegalStateException.class)
    public void testTryFinallyThrowsWhenTryBodyIsNotLabelName() {
        // Create a node that is NOT a label name (e.g., a simple expression)
        Node tryBody = IR.number(1); 
        Node finallyBody = IR.labelName("finallyLabel");

        // This should trigger Preconditions.checkState(tryBody.isLabelName())
        IR.tryFinally(tryBody, finallyBody);
    }

    @Test(expected = IllegalStateException.class)
    public void testTryFinallyThrowsWhenFinallyBodyIsNotLabelName() {
        // Create a node that is NOT a label name
        Node tryBody = IR.labelName("tryLabel");
        Node finallyBody = IR.number(2);

        // This should trigger Preconditions.checkState(finallyBody.isLabelName())
        IR.tryFinally(tryBody, finallyBody);
    }

    @Test(expected = IllegalStateException.class)
    public void testTryFinallyThrowsWhenBothAreNotLabelNames() {
        // Both invalid
        Node tryBody = IR.number(1);
        Node finallyBody = IR.number(2);

        IR.tryFinally(tryBody, finallyBody);
    }
}
